const DEFAULT_RETELL_API_KEY = "";
const DEFAULT_FIRECRAWL_API_KEY = "";
let envApiKey = "";
try {
  envApiKey = (typeof $env !== "undefined" && $env && $env.RETELL_API_KEY) || "";
} catch (e) {
  envApiKey = "";
}
let envFirecrawlApiKey = "";
try {
  envFirecrawlApiKey = (typeof $env !== "undefined" && $env && $env.FIRECRAWL_API_KEY) || "";
} catch (e) {
  envFirecrawlApiKey = "";
}

let inputUrl = "";
let isWebhook = false;
let retellApiKey = DEFAULT_RETELL_API_KEY || envApiKey;
let firecrawlApiKey = DEFAULT_FIRECRAWL_API_KEY || envFirecrawlApiKey;

if ($json.headers !== undefined) {
  isWebhook = true;
  if ($json.body && typeof $json.body.url === "string") {
    inputUrl = $json.body.url;
  } else if ($json.query && typeof $json.query.url === "string") {
    inputUrl = $json.query.url;
  } else if (typeof $json.url === "string") {
    inputUrl = $json.url;
  }
  if ($json.body && typeof $json.body.retell_api_key === "string") {
    retellApiKey = $json.body.retell_api_key;
  } else if ($json.headers && $json.headers["x-retell-api-key"]) {
    retellApiKey = $json.headers["x-retell-api-key"];
  }
  if ($json.body && typeof $json.body.firecrawl_api_key === "string") {
    firecrawlApiKey = $json.body.firecrawl_api_key;
  } else if ($json.headers && $json.headers["x-firecrawl-api-key"]) {
    firecrawlApiKey = $json.headers["x-firecrawl-api-key"];
  }
} else if (typeof $json.url === "string") {
  inputUrl = $json.url;
  if (typeof $json.retell_api_key === "string") {
    retellApiKey = $json.retell_api_key;
  }
  if (typeof $json.firecrawl_api_key === "string") {
    firecrawlApiKey = $json.firecrawl_api_key;
  }
}

if (!inputUrl || typeof inputUrl !== "string" || inputUrl.trim() === "") {
  return [
    {
      json: {
        valid: false,
        url: "",
        mainUrl: "",
        pageType: "invalid",
        scrapeError:
          'A website URL is required. Send {"url":"https://example.com"} to the webhook or pin a test item with a url field.',
        scrapeSuccess: false,
        statusCode: 422,
        pagesFetched: 0,
        pagesAttempted: 0,
        failedPages: [],
        retellApiKey: String(retellApiKey || "").trim(),
        firecrawlApiKey: String(firecrawlApiKey || "").trim(),
        isWebhook: isWebhook,
        timestamp: new Date().toISOString()
      }
    }
  ];
}

inputUrl = inputUrl.trim();
if (!/^https?:\/\//i.test(inputUrl)) {
  inputUrl = "https://" + inputUrl;
}

const originMatch = inputUrl.match(/^(https?:\/\/[^\/?#]+)/i);
if (!originMatch) {
  return [
    {
      json: {
        valid: false,
        url: inputUrl,
        mainUrl: "",
        pageType: "invalid",
        scrapeError: "That website URL is not valid: " + inputUrl,
        scrapeSuccess: false,
        statusCode: 422,
        pagesFetched: 0,
        pagesAttempted: 0,
        failedPages: [],
        retellApiKey: String(retellApiKey || "").trim(),
        firecrawlApiKey: String(firecrawlApiKey || "").trim(),
        isWebhook: isWebhook,
        timestamp: new Date().toISOString()
      }
    }
  ];
}

const origin = originMatch[1].replace(/\/+$/, "");
const hostname = origin
  .replace(/^https?:\/\//i, "")
  .split(":")[0]
  .replace(/^www\./i, "")
  .toLowerCase();

const isPrivate =
  !hostname.includes(".") ||
  /\.local$/i.test(hostname) ||
  /^(localhost|0\.0\.0\.0|127\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.)/i.test(hostname);

if (isPrivate) {
  return [
    {
      json: {
        valid: false,
        url: inputUrl,
        mainUrl: "",
        pageType: "invalid",
        scrapeError: "Please provide a public website URL. Local and private network addresses are not supported.",
        scrapeSuccess: false,
        statusCode: 422,
        pagesFetched: 0,
        pagesAttempted: 0,
        failedPages: [],
        retellApiKey: String(retellApiKey || "").trim(),
        firecrawlApiKey: String(firecrawlApiKey || "").trim(),
        isWebhook: isWebhook,
        timestamp: new Date().toISOString()
      }
    }
  ];
}

const homeUrl = inputUrl.replace(/#.*$/, "");
const candidates = [
  { url: homeUrl, pageType: "home" },
  { url: `${origin}/pricing`, pageType: "pricing" },
  { url: `${origin}/plans`, pageType: "pricing" },
  { url: `${origin}/products`, pageType: "products" },
  { url: `${origin}/services`, pageType: "services" },
  { url: `${origin}/about`, pageType: "about" },
  { url: `${origin}/about-us`, pageType: "about" },
  { url: `${origin}/contact`, pageType: "contact" },
  { url: `${origin}/faq`, pageType: "faq" }
];

const seen = new Set();
const crawlTargets = [];
for (const target of candidates) {
  const key = target.url.replace(/\/+$/, "").toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  crawlTargets.push(target);
}

return crawlTargets.map((target) => ({
  json: {
    valid: true,
    url: target.url,
    mainUrl: origin,
    pageType: target.pageType,
    retellApiKey: String(retellApiKey || "").trim(),
    firecrawlApiKey: String(firecrawlApiKey || "").trim(),
    isWebhook: isWebhook,
    timestamp: new Date().toISOString()
  }
}));

const DEFAULT_FIRECRAWL_API_KEY = "";

const items = $input.all();
const first = items[0]?.json || {};

let envFirecrawlApiKey = "";
try {
  envFirecrawlApiKey = (typeof $env !== "undefined" && $env && $env.FIRECRAWL_API_KEY) || "";
} catch (e) {
  envFirecrawlApiKey = "";
}

const firecrawlApiKey = String(
  DEFAULT_FIRECRAWL_API_KEY || envFirecrawlApiKey || first.firecrawlApiKey || "",
).trim();
const useFirecrawl = Boolean(firecrawlApiKey);

const FIRECRAWL_TYPES = new Set(["home", "about", "pricing", "contact"]);
const firecrawlClaimed = new Set();

const NATIVE_HEADERS = {
  "User-Agent":
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
  Accept: "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
  "Accept-Language": "en-US,en;q=0.9",
  "Cache-Control": "no-cache"
};

function cleanText(value) {
  return String(value == null ? "" : value).replace(/\s+/g, " ").trim();
}

async function mapLimit(list, limit, fn) {
  const output = new Array(list.length);
  let cursor = 0;
  const workers = Array.from({ length: Math.min(limit, list.length) }, async () => {
    while (cursor < list.length) {
      const index = cursor;
      cursor += 1;
      output[index] = await fn(list[index], index);
    }
  });
  await Promise.all(workers);
  return output;
}

const fetchNative = async (target) => {
  const response = await this.helpers.httpRequest({
    method: "GET",
    url: target.url,
    headers: NATIVE_HEADERS,
    timeout: 15000,
    json: false,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });

  const body =
    typeof response.body === "string" ? response.body : JSON.stringify(response.body == null ? "" : response.body);

  return {
    statusCode: Number(response.statusCode || 0),
    body
  };
};

const fetchFirecrawl = async (target) => {
  const response = await this.helpers.httpRequest({
    method: "POST",
    url: "https://api.firecrawl.dev/v1/scrape",
    headers: {
      Authorization: `Bearer ${firecrawlApiKey}`,
      "Content-Type": "application/json"
    },
    body: {
      url: target.url,
      formats: ["markdown"],
      onlyMainContent: true
    },
    timeout: 25000,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });

  let payload = response.body;
  if (typeof payload === "string") {
    try {
      payload = JSON.parse(payload);
    } catch (e) {
      payload = {};
    }
  }

  const data = (payload && payload.data) || {};
  const metadata = data.metadata || {};
  const markdown = cleanText(data.markdown || "");
  const statusCode = Number(metadata.statusCode || response.statusCode || 0);

  if (!payload || payload.success === false || statusCode >= 400 || markdown.length < 200) {
    throw new Error(
      `Firecrawl returned no usable content (${markdown.length} chars, status ${statusCode || "unknown"})`,
    );
  }

  return {
    statusCode,
    body: markdown,
    pageTitle: cleanText(metadata.title || metadata.ogTitle || ""),
    metaDescription: cleanText(metadata.description || metadata.ogDescription || ""),
    source: "firecrawl"
  };
};

return (async () => {
  const results = await mapLimit(items, 4, async (item) => {
    const target = item.json || {};
    const pageType = target.pageType || "home";
    const base = {
      url: target.url,
      mainUrl: target.mainUrl || "",
      pageType,
      isWebhook: Boolean(target.isWebhook),
      retellApiKey: target.retellApiKey || "",
      firecrawlApiKey: target.firecrawlApiKey || ""
    };

    const firecrawlEligible =
      useFirecrawl && FIRECRAWL_TYPES.has(pageType) && !firecrawlClaimed.has(pageType);

    if (firecrawlEligible) {
      firecrawlClaimed.add(pageType);
      try {
        const result = await fetchFirecrawl(target);
        return {
          json: {
            ...base,
            statusCode: result.statusCode,
            body: result.body,
            pageTitle: result.pageTitle,
            metaDescription: result.metaDescription,
            source: result.source
          }
        };
      } catch (e) {
        // Fall back to the native fetch below.
      }
    }

    try {
      const result = await fetchNative(target);
      return {
        json: {
          ...base,
          statusCode: result.statusCode,
          body: result.body,
          pageTitle: "",
          metaDescription: "",
          source: "http"
        }
      };
    } catch (e) {
      return {
        json: {
          ...base,
          statusCode: 0,
          body: "",
          pageTitle: "",
          metaDescription: "",
          source: "error",
          error: String(e && e.message ? e.message : e)
        }
      };
    }
  });

  return results;
})();

﻿const allItems = $input.all();
const firstItem = allItems[0]?.json || {};
const targetUrl = firstItem.mainUrl || firstItem.url || "";
const isWebhook = Boolean(firstItem.isWebhook);
const retellApiKey = firstItem.retellApiKey || "";

let pageTitle = "";
let metaDesc = "";
const headings = [];
const pricingSnippets = [];
const faqSnippets = [];
const locationSnippets = [];
const generalSnippets = [];
const failedPages = [];
const statusCodes = [];
let successfulPages = 0;
let totalTextLength = 0;
let blocked = false;

function decodeEntities(value) {
  return String(value || "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, "\"")
    .replace(/&#0*39;|&apos;|&#x27;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&mdash;/gi, "-")
    .replace(/&ndash;/gi, "-")
    .replace(/&hellip;/gi, "...")
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/\s+/g, " ")
    .trim();
}

function addUnique(list, value, max, minLength) {
  const text = decodeEntities(value).replace(/\s+/g, " ").trim();
  if (text.length < minLength) return;
  if (list.some((item) => item.toLowerCase() === text.toLowerCase())) return;
  if (list.length < max) list.push(text);
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const text = decodeEntities(value);
    if (text) return text;
  }
  return "";
}

function looksLikeAddress(text) {
  if (!text || text.length > 320) return false;
  if (
    /\b(your location|location[- ]based|tax(?:es)?|shipping|delivery|billing address|api|json|sdk|browser|settings|language|country selector)\b/i.test(
      text,
    )
  ) {
    return false;
  }

  if (
    /\b\d{1,6}\s+[A-Za-z0-9][A-Za-z0-9.'-]*(?:\s+[A-Za-z0-9][A-Za-z0-9.'-]*){0,5}\s+(?:street|st|road|rd|avenue|ave|boulevard|blvd|lane|ln|drive|dr|way|place|pl|court|ct|highway|hwy|parkway|pkwy)\b/i.test(
      text,
    )
  ) {
    return true;
  }

  if (/\b[A-Z][a-z]+(?:\s+[A-Z][a-z]+)*,\s*(?:[A-Z]{2}|[A-Z][a-z]+)\s+\d{5}(?:-\d{4})?\b/.test(text)) return true;
  if (/\b\d{6}\b/.test(text) && /\b(?:sector|plot|road|street|building|tower|floor|near|industrial|tech park)\b/i.test(text)) return true;

  return (
    /\b(?:headquarters|head office|main office|corporate office|our office|visit us at|located at|located in|based in)\b/i.test(
      text,
    ) && !/\bbased on\b/i.test(text)
  );
}

function looksLikePricing(text, isPricingPage) {
  if (!text || text.length > 320) return false;
  if (
    /^(?:watch|read|learn|see how|discover|explore|contact|get started)\b/i.test(text) ||
    /\b(?:news|story|blog|careers|partner program|customer story|case study|offers .* with|grows into|partners with)\b/i.test(
      text,
    )
  ) {
    return false;
  }

  const hasPrice =
    /(?:[$€£₹]\s?\d|\d+(?:\.\d+)?\s?%|\b(?:free|trial|starting at|per month|per user|per seat|usage-based|annual|monthly|hourly)\b)/i.test(
      text,
    );
  if (!hasPrice) return false;

  if (isPricingPage) return true;
  return /\b(?:price|pricing|plans?|cost|fee|fees|subscription|billing|quote|charged|charge|rate|rates)\b/i.test(text);
}

for (const item of allItems) {
  const data = item.json || {};
  const pageType = data.pageType || "home";
  const status = Number(data.statusCode || data.status || 0);
  if (status) statusCodes.push(status);

  const rawHtml =
    typeof data.body === "string"
      ? data.body
      : typeof data.data === "string"
        ? data.data
        : typeof data.html === "string"
          ? data.html
          : "";

  if (status >= 400) {
    failedPages.push(`${pageType}: HTTP ${status}`);
    continue;
  }

  if (data.error || !rawHtml || rawHtml.length < 200) {
    failedPages.push(`${pageType}: empty response`);
    continue;
  }

  if (
    /cf-browser-verification|challenge-platform|Just a moment\.\.\.|Attention Required!|Access denied/i.test(rawHtml) &&
    rawHtml.length < 20000
  ) {
    blocked = true;
    failedPages.push(`${pageType}: blocked by bot protection`);
    continue;
  }

  const titleMatch = rawHtml.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const pageTitleCandidate = titleMatch ? decodeEntities(titleMatch[1]) : "";
  const metaMatch =
    rawHtml.match(/<meta[^>]+(?:name=['"]description['"]|property=['"]og:description['"])[^>]+content=['"]([^'"]*)['"]/i) ||
    rawHtml.match(/<meta[^>]+content=['"]([^'"]*)['"][^>]+(?:name=['"]description['"]|property=['"]og:description['"])/i);
  const metaCandidate = metaMatch ? decodeEntities(metaMatch[1]) : "";

  if (!pageTitle) pageTitle = decodeEntities(data.pageTitle || data.title || "") || pageTitleCandidate;
  if (!metaDesc) metaDesc = decodeEntities(data.metaDescription || data.description || "") || metaCandidate;

  let cleaned = rawHtml
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, " ")
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, " ")
    .replace(/<svg\b[^<]*(?:(?!<\/svg>)<[^<]*)*<\/svg>/gi, " ")
    .replace(/<noscript\b[^<]*(?:(?!<\/noscript>)<[^<]*)*<\/noscript>/gi, " ")
    .replace(/<template\b[^<]*(?:(?!<\/template>)<[^<]*)*<\/template>/gi, " ")
    .replace(/<nav\b[^<]*(?:(?!<\/nav>)<[^<]*)*<\/nav>/gi, " ")
    .replace(/<header\b[^<]*(?:(?!<\/header>)<[^<]*)*<\/header>/gi, " ")
    .replace(/<!--[\s\S]*?-->/g, " ")
    .replace(/!\[[^\]]*\]\([^)]+\)/g, " ")
    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1");

  const headingMatches = cleaned.matchAll(/<(h[1-3])[^>]*>([\s\S]*?)<\/\1>/gi);
  for (const match of headingMatches) {
    const text = decodeEntities(match[2].replace(/<[^>]+>/g, " "));
    if (/^(home|about|contact|login|sign in|sign up|menu|search|blog|careers|privacy|terms)$/i.test(text)) continue;
    addUnique(headings, text, 14, 3);
  }

  const mdHeadingMatches = cleaned.matchAll(/^#{1,3}\s+([^\n#]{3,120})$/gm);
  for (const match of mdHeadingMatches) {
    const text = decodeEntities(match[1]);
    if (/^(home|about|contact|login|sign in|sign up|menu|search|blog|careers|privacy|terms)$/i.test(text)) continue;
    addUnique(headings, text, 14, 3);
  }

  const text = decodeEntities(
    cleaned
      .replace(/<[^>]+>/g, " ")
      .replace(/^\s{0,3}[#>*+-]+\s*/gm, " ")
      .replace(/[*_`~]/g, " "),
  );
  totalTextLength += text.length;
  successfulPages += 1;

  const sentences = text
    .split(/[.!?]\s+/)
    .map((sentence) => sentence.trim())
    .filter((sentence) => sentence.length >= 25);

  const isContactPage = pageType === "contact";
  const isPricingPage = pageType === "pricing" || pageType === "plans";
  const isFaqPage = pageType === "faq";

  for (const sentence of sentences) {
    if (locationSnippets.length < 2 && sentence.length <= 300) {
      const contactAddress =
        isContactPage &&
        /\b(?:address|headquarters|head office|located|location|visit us|our office)\b/i.test(sentence) &&
        !/\b(?:null|json|api|tax|shipping|billing)\b/i.test(sentence);
      if (looksLikeAddress(sentence) || contactAddress) {
        addUnique(locationSnippets, sentence, 2, 20);
      }
    }

    if (pricingSnippets.length < 3 && looksLikePricing(sentence, isPricingPage)) {
      addUnique(pricingSnippets, sentence, 3, 15);
    }

    if (
      generalSnippets.length < 8 &&
      sentence.length >= 50 &&
      sentence.length <= 300 &&
      !/\b(cookie|privacy policy|terms of service|all rights reserved|copyright|©|subscribe|newsletter|javascript)\b/i.test(sentence)
    ) {
      addUnique(generalSnippets, sentence, 8, 40);
    }
  }

  const qaMatches = text.matchAll(/([A-Z][^?]{10,100}\?)\s+([^?]{20,240}[.!?])/g);
  for (const match of qaMatches) {
    if (faqSnippets.length >= 4) break;
    const qa = `${decodeEntities(match[1])} ${decodeEntities(match[2])}`;
    const relevant =
      isFaqPage ||
      /\b(?:pricing|price|plan|support|trial|refund|shipping|account|security|privacy|integration|api|product|service|cancel|contact)\b/i.test(
        qa,
      );
    if (
      relevant &&
      !/\b(?:cookie|privacy|terms)\b/i.test(qa) &&
      !/\b(?:ready to get started|watch the video|read more|subscribe|newsletter)\b/i.test(qa)
    ) {
      addUnique(faqSnippets, qa, 4, 30);
    }
  }
}

const hardErrorTitle = /^(404|403|500|502|503)\b|page not found|domain (is )?for sale|under construction|coming soon|just a moment|attention required/i;
const hasReadableContent = Boolean(pageTitle || metaDesc || headings.length || generalSnippets.length) && totalTextLength >= 150;
const errorTitle = hardErrorTitle.test(pageTitle);
const scrapeSuccess = successfulPages > 0 && hasReadableContent && !errorTitle;

let scrapeError = "";
if (!scrapeSuccess) {
  if (blocked) {
    scrapeError = "The website blocked the scraper with bot protection or a JavaScript challenge.";
  } else if (errorTitle) {
    scrapeError = `The website returned an error or placeholder page (${pageTitle || "unknown title"}).`;
  } else if (successfulPages === 0) {
    scrapeError = "No pages could be fetched. The website may be offline, blocking requests, or returning errors.";
  } else {
    scrapeError = "The fetched pages did not contain enough readable company content. The site may render its content with JavaScript.";
  }
}

const condensedContext = [
  `COMPANY TARGET: ${targetUrl}`,
  `PAGE TITLE: ${pageTitle || "Not found"}`,
  `META DESCRIPTION: ${metaDesc || "Not found"}`,
  `SCRAPE COVERAGE: ${successfulPages} of ${allItems.length} pages fetched`,
  "",
  "LOCATION / ADDRESS:",
  locationSnippets.length ? locationSnippets.join("\n") : "Not found in scraped pages.",
  "",
  "PRICING / FEES:",
  pricingSnippets.length ? pricingSnippets.join("\n") : "Not found in scraped pages.",
  "",
  "FAQ / POLICIES:",
  faqSnippets.length ? faqSnippets.join("\n") : "Not found in scraped pages.",
  "",
  "HEADINGS / OFFERINGS:",
  headings.length ? headings.join("\n") : "Not found in scraped pages.",
  "",
  "KEY EXCERPTS:",
  generalSnippets.length ? generalSnippets.join("\n") : "Not found in scraped pages."
]
  .join("\n")
  .trim();

return [
  {
    json: {
      url: targetUrl,
      isWebhook: isWebhook,
      retellApiKey: retellApiKey,
      pageTitle: pageTitle,
      metaDescription: metaDesc,
      extractedContext: condensedContext,
      scrapeSuccess: scrapeSuccess,
      scrapeError: scrapeError,
      pagesFetched: successfulPages,
      pagesAttempted: allItems.length,
      failedPages: failedPages,
      statusCodes: statusCodes,
      locationData: locationSnippets.join("; "),
      pricingData: pricingSnippets.join("; "),
      faqData: faqSnippets.join("; "),
      headings: headings.slice(0, 10),
      generalSnippets: generalSnippets.slice(0, 6)
    }
  }
];

const source = $("Extract & Validate URL").first().json || {};
const targetUrl = source.mainUrl || source.url || "";
const isWebhook = Boolean(source.isWebhook);
const userApiKey = source.retellApiKey || "";

let cleanedData = {};
try {
  cleanedData = $("Parse & Clean Content").first().json || {};
} catch (e) {
  cleanedData = {};
}

const pageTitle = cleanedData.pageTitle || "";
const metaDesc = cleanedData.metaDescription || "";
const condensedContext = cleanedData.extractedContext || "";
const headings = Array.isArray(cleanedData.headings) ? cleanedData.headings : [];
const domain = targetUrl
  .replace(/^https?:\/\//i, "")
  .replace(/^www\./i, "")
  .split("/")[0];
const fallbackName = domain ? domain.charAt(0).toUpperCase() + domain.slice(1).split(".")[0] : "Company";

function cleanText(value) {
  return String(value == null ? "" : value).replace(/\s+/g, " ").trim();
}

function toList(value) {
  if (Array.isArray(value)) {
    return value.map(cleanText).filter(Boolean);
  }
  if (typeof value === "string") {
    return value
      .split(/[,\n;]/)
      .map(cleanText)
      .filter(Boolean);
  }
  return [];
}

const PROMPT_ARTIFACT =
  /(?:\bor an empty string\b|\bif unclear\b|\bif not stated\b|\bgrounded in the context\b|\b1 crisp sentence\b|\b2 short sentences\b|\bProduct 1\b|\bProduct 2\b|\bTag1\b|\bTag2\b|\bCompany Name\b|\bTarget customers\b|\bIndustry name\b|\bempty array\b)/i;
const STOP_WORDS = new Set([
  "that",
  "with",
  "this",
