return [
  {
    json: {
      output: reply,
      company_name: companyName,
      website_url: targetUrl,
      generated_at: new Date().toISOString()
    }
  }
];

const body = $json.body || $json;
const userMsg = String(body.message || body.content || body.chatInput || "").trim();
const chatId = body.chat_id || "";
const agentId = body.agent_id || "";

let stored = {};
try {
  const store = $getWorkflowStaticData("global");
  const key = String(body.website_url || "").replace(/\/+$/, "").toLowerCase();
  const briefs = store.briefs || {};
  stored = (key && briefs[key]) || store.latestBrief || {};
} catch (e) {
  stored = {};
}

const companyName = String(body.company_name || stored.company_name || "").trim();
const targetUrl = String(body.website_url || stored.website_url || "").trim();
const site = targetUrl || "the company website";
const siteLabel = targetUrl.replace(/^https?:\/\//i, "").replace(/\/+$/, "");
const summary = String(body.what_the_company_does || stored.what_the_company_does || "").trim();
const oneLiner = String(body.one_liner || stored.one_liner || "").trim();
const audience = String(body.primary_target_audience || stored.primary_target_audience || "").trim();
const location = String(body.location_info || stored.location_info || "").trim();
const pricing = String(body.pricing_info || stored.pricing_info || "").trim();
const faq = String(body.faq_info || stored.faq_info || "").trim();
const context = String(body.website_context || stored.website_context || "").trim();

function toList(value) {
  if (Array.isArray(value)) return value.map((item) => String(item).trim()).filter(Boolean);
  if (typeof value === "string") return value.split(/[,\n]/).map((item) => item.trim()).filter(Boolean);
  return [];
}

const products = toList(body.key_products_or_services || stored.key_products_or_services);

function clean(value) {
  return String(value == null ? "" : value).replace(/\s+/g, " ").trim();
}

function trimTo(value, max) {
  const text = clean(value);
  if (text.length <= max) return text;
  const cut = text.slice(0, max);
  return `${cut.slice(0, Math.max(0, cut.lastIndexOf(" "))).trim()}...`;
}

function relevantExcerpt(query) {
  const stopWords = new Set([
    "the", "and", "for", "with", "about", "from", "this", "that", "your", "you", "are", "can",
    "what", "how", "does", "company", "website", "please", "tell", "have", "has", "our", "their",
    "they", "will", "would", "could", "should", "there", "here", "when", "where", "which", "who",
    "why", "into", "over", "under", "more", "most", "some", "any", "all", "not", "but", "its"
  ]);
  const words = String(query || "")
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((word) => word.length >= 4 && !stopWords.has(word));
  if (!words.length) return "";

  const chunks = context
    .split(/\n+|[.!?]\s+/)
    .map(clean)
    .filter((chunk) => chunk.length >= 30)
    .filter((chunk) => !/^(COMPANY TARGET|PAGE TITLE|META DESCRIPTION|SCRAPE COVERAGE|LOCATION \/ ADDRESS|PRICING \/ FEES|FAQ \/ POLICIES|HEADINGS \/ OFFERINGS|KEY EXCERPTS)/i.test(chunk));

  let best = { score: 0, text: "" };
  for (const chunk of chunks) {
    const lower = chunk.toLowerCase();
    const score = words.reduce((total, word) => total + (lower.includes(word) ? 1 : 0), 0);
    if (score > best.score) best = { score, text: chunk };
  }
  return best.score >= 2 ? trimTo(best.text, 300) : "";
}

if (!userMsg) {
  return [{ json: { reply: "Please send a question about the company.", company_name: companyName, agent_id: agentId, chat_id: chatId, timestamp: new Date().toISOString() } }];
}

if (!companyName && !targetUrl) {
  return [{ json: { reply: "No company has been researched yet. Run a website scrape first, then I can answer questions about that company.", company_name: "", agent_id: agentId, chat_id: chatId, timestamp: new Date().toISOString() } }];
}

const name = companyName || "this company";
const q = userMsg.toLowerCase();
const excerpt = relevantExcerpt(q);
const contactHint = targetUrl
  ? `You can find current contact details on the contact page at ${targetUrl}.`
  : "You can find current contact details on the company website.";

let reply = "";

if (/\b(sex|sexy|porn|nude|nsfw|fuck|bitch|penis|vagina|boobs|asshole|bastard|blowjob|dick|pussy|whore|slut|erotic|hooker)\b/i.test(q)) {
  reply = `I can only help with questions about ${name}. Please ask about our products, services, pricing, or support.`;
} else if (/\b(where|location|address|place|city|state|campus|branch|office|located|directions|reach us)\b/i.test(q)) {
  reply = location
    ? `Here is the location information from the scraped website: ${trimTo(location, 360)}`
    : `I do not have a verified address in the scraped content for ${name}. ${contactHint}`;
} else if (/\b(price|pricing|charge|charges|fee|fees|cost|costs|rate|rates|subscription|billing|quote|how much)\b/i.test(q)) {
  reply = pricing
    ? `Here is the pricing information from the scraped website: ${trimTo(pricing, 360)}`
    : `I could not find pricing in the scraped pages for ${name}. ${targetUrl ? `Check ${targetUrl} or contact the team for a current quote.` : "Please check the website or contact the team for a current quote."}`;
} else if (/\b(faq|support|help|guarantee|sla|security|policy|policies|refund|shipping|delivery)\b/i.test(q)) {
  if (faq) {
    reply = `The website's FAQ or policy content says: ${trimTo(faq, 360)}`;
  } else if (excerpt) {
    reply = `Here is a relevant excerpt from the website: ${excerpt}`;
  } else {
    reply = `I could not find a support or policy answer in the scraped pages. ${contactHint}`;
  }
} else if (/\b(product|products|service|services|offer|offerings|feature|features|solution|solutions)\b/i.test(q)) {
  reply = products.length
    ? `${name}'s key offerings from the website include: ${products.slice(0, 6).join(", ")}.`
    : `I could not find a product or service list in the scraped pages. ${targetUrl ? `Visit ${targetUrl} to see current offerings.` : "Please check the website for current offerings."}`;
} else if (/\b(audience|who is|who can|who are|target|eligible|for who|market)\b/i.test(q)) {
  reply = audience && !/^not specified/i.test(audience)
    ? `The website describes the target audience as: ${audience}`
    : excerpt || `I could not find an explicit audience description in the scraped pages. ${targetUrl ? `Visit ${targetUrl} to learn more.` : ""}`.trim();
} else if (/\b(contact|email|phone|call|whatsapp|reach)\b/i.test(q)) {
  reply = location
    ? `Contact or location details from the website: ${trimTo(location, 300)}${targetUrl ? ` More details are available at ${targetUrl}.` : ""}`
    : `For current contact details, visit ${targetUrl || "the company website"}.`;
} else if (/\b(hello|hi|hey|good morning|good afternoon|good evening)\b/i.test(q)) {
  reply = `Hello! I'm the AI customer agent for ${name}. I can answer questions using the content scraped from ${siteLabel || site}. What would you like to know?`;
} else if (/\b(tagline|elevator|one liner|about|summar|overview|what do you do)\b/i.test(q)) {
  const about = oneLiner && !summary ? oneLiner : summary;
  reply = about
    ? `${name}: ${trimTo(about, 320)}`
    : excerpt || `I do not have a verified summary for ${name} in the scraped content. ${targetUrl ? `Visit ${targetUrl} to learn more.` : ""}`.trim();
} else if (excerpt) {
  reply = `Here is a relevant excerpt from ${name}'s website: ${excerpt}`;
} else if (summary) {
  reply = `${name}: ${trimTo(summary, 320)}${products.length ? ` Key offerings include ${products.slice(0, 4).join(", ")}.` : ""}`;
} else {
  reply = `I do not have enough scraped information to answer that. ${targetUrl ? `Visit ${targetUrl} or ask about products, pricing, location, or support.` : "Please ask about products, pricing, location, or support."}`;
}

return [
  {
    json: {
      reply: reply,
      company_name: companyName,
      agent_id: agentId,
      chat_id: chatId,
      timestamp: new Date().toISOString()
    }
  }
];

const failed = $json || {};
const message = failed.scrapeError || "The website could not be scraped.";

return [
  {
    json: {
      ok: false,
      error: "SCRAPE_FAILED",
      detail: message,
      message: message,
      scrape_status: "error",
      company_name: "",
      website_url: failed.url || "",
      pages_fetched: failed.pagesFetched || 0,
      pages_attempted: failed.pagesAttempted || 0,
      failed_pages: failed.failedPages || [],
      statusCode: 422,
      _isWebhook: Boolean(failed.isWebhook)
    }
  }
];
